# ---------------------------------------------------------------------------
# Schema Constants (mirror of TypeScript definitions)
# ---------------------------------------------------------------------------

RESOURCE_TYPES = {"Deployment", "Service", "Ingress", "ConfigMap", "Secret"}
SERVICE_TYPES = {"ClusterIP", "NodePort", "LoadBalancer"}

# Required top-level keys
REQUIRED_TOP_LEVEL = {"version", "metadata", "resources"}
REQUIRED_METADATA = {"name", "namespace"}
REQUIRED_RESOURCE = {"type", "name", "spec"}

# Valid resource type -> allowed spec keys mapping
RESOURCE_SPEC_KEYS = {
    "Deployment": {"replicas", "image", "ports", "env", "resources"},
    "Service": {"serviceType", "targetPort", "port", "ports"},
    "Ingress": {"host", "paths"},
    "ConfigMap": {"env", "data"},
    "Secret": {"env", "data"},
}

# Type constraints per field
FIELD_TYPES: Dict[str, type] = {
    "version": str,
    "name": str,
    "namespace": str,
    "type": str,
    "replicas": int,
    "image": str,
    "serviceType": str,
    "targetPort": int,
    "port": int,
    "host": str,
}

# Port range constraints
PORT_MIN = 1
PORT_MAX = 65535
REPLICA_MIN = 0
REPLICA_MAX = 1000

# ---------------------------------------------------------------------------
# Validation Helpers (mirror of runtime validators)
# ---------------------------------------------------------------------------


def _validate_top_level(payload: Dict[str, Any]) -> List[str]:
    """Return list of missing required top-level keys."""
    return [k for k in REQUIRED_TOP_LEVEL if k not in payload]


def _validate_metadata(metadata: Any) -> List[str]:
    """Validate metadata object shape."""
    errors = []
    if not isinstance(metadata, dict):
        return ["metadata must be an object"]
    for k in REQUIRED_METADATA:
        if k not in metadata:
            errors.append(f"metadata.{k} is required")
    if "name" in metadata and not isinstance(metadata["name"], str):
        errors.append("metadata.name must be a string")
    if "namespace" in metadata and not isinstance(metadata["namespace"], str):
        errors.append("metadata.namespace must be a string")
    return errors


def _validate_resource(resource: Any) -> List[str]:
    """Validate a single resource object."""
    errors = []
    if not isinstance(resource, dict):
        return ["resource must be an object"]

    for k in REQUIRED_RESOURCE:
        if k not in resource:
            errors.append(f"resource.{k} is required")

    if "type" in resource and resource["type"] not in RESOURCE_TYPES:
        errors.append(f"resource.type must be one of {sorted(RESOURCE_TYPES)}")

    if "name" in resource and not isinstance(resource["name"], str):
        errors.append("resource.name must be a string")

    if "spec" in resource:
        spec_errors = _validate_spec(resource["type"], resource["spec"])
        errors.extend(spec_errors)

    return errors


def _validate_spec(resource_type: str, spec: Any) -> List[str]:
    """Validate resource spec based on type."""
    errors = []
    if not isinstance(spec, dict):
        return ["spec must be an object"]

    allowed_keys = RESOURCE_SPEC_KEYS.get(resource_type, set())
    unknown_keys = set(spec.keys()) - allowed_keys
    if unknown_keys:
        errors.append(f"spec has unknown keys for {resource_type}: {sorted(unknown_keys)}")

    # Type-specific validation
    if resource_type == "Deployment":
        if "replicas" in spec:
            if not isinstance(spec["replicas"], int) or isinstance(spec["replicas"], bool):
                errors.append("Deployment.spec.replicas must be an integer")
            elif not (REPLICA_MIN <= spec["replicas"] <= REPLICA_MAX):
                errors.append(f"Deployment.spec.replicas must be in [{REPLICA_MIN}, {REPLICA_MAX}]")
        if "image" in spec and not isinstance(spec["image"], str):
            errors.append("Deployment.spec.image must be a string")

    elif resource_type == "Service":
        if "serviceType" in spec:
            if spec["serviceType"] not in SERVICE_TYPES:
                errors.append(f"Service.spec.serviceType must be one of {sorted(SERVICE_TYPES)}")
        if "targetPort" in spec:
            if not isinstance(spec["targetPort"], int) or isinstance(spec["targetPort"], bool):
                errors.append("Service.spec.targetPort must be an integer")
            elif not (PORT_MIN <= spec["targetPort"] <= PORT_MAX):
                errors.append(f"Service.spec.targetPort must be in [{PORT_MIN}, {PORT_MAX}]")
        if "port" in spec:
            if not isinstance(spec["port"], int) or isinstance(spec["port"], bool):
                errors.append("Service.spec.port must be an integer")
            elif not (PORT_MIN <= spec["port"] <= PORT_MAX):
                errors.append(f"Service.spec.port must be in [{PORT_MIN}, {PORT_MAX}]")

    elif resource_type == "Ingress":
        if "host" in spec and not isinstance(spec["host"], str):
            errors.append("Ingress.spec.host must be a string")
        if "paths" in spec:
            if not isinstance(spec["paths"], list):
                errors.append("Ingress.spec.paths must be an array")
            else:
                for p in spec["paths"]:
                    if not isinstance(p, str):
                        errors.append("Ingress.spec.paths entries must be strings")

    elif resource_type in ("ConfigMap", "Secret"):
        if "data" in spec and not isinstance(spec["data"], dict):
            errors.append(f"{resource_type}.spec.data must be an object")
        if "env" in spec and not isinstance(spec["env"], dict):
            errors.append(f"{resource_type}.spec.env must be an object")

    return errors


def _validate_resources(resources: Any) -> List[str]:
    """Validate the resources array."""
    errors = []
    if not isinstance(resources, list):
        return ["resources must be an array"]
    if len(resources) == 0:
        errors.append("resources must not be empty")
    for i, r in enumerate(resources):
        for err in _validate_resource(r):
            errors.append(f"resources[{i}].{err}")
    return errors


def validate_infra_spec(payload: Dict[str, Any]) -> List[str]:
    """Full schema validation. Returns list of error strings (empty = valid)."""
    errors = []
    errors.extend(_validate_top_level(payload))

    if "metadata" in payload:
        errors.extend(_validate_metadata(payload["metadata"]))

    if "resources" in payload:
        errors.extend(_validate_resources(payload["resources"]))

    if "version" in payload and not isinstance(payload["version"], str):
        errors.append("version must be a string")

    return errors


