@st.composite
def valid_metadata_strategy(draw: st.DrawFn) -> Dict[str, str]:
    """Generate valid metadata objects."""
    return {
        "name": draw(st.text(min_size=1, max_size=63, alphabet=st.characters(whitelist_categories=("Ll", "Lu", "Nd", "-")))),
        "namespace": draw(st.text(min_size=1, max_size=63, alphabet=st.characters(whitelist_categories=("Ll", "Lu", "Nd", "-")))),
    }


@st.composite
def deployment_spec_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate valid Deployment specs."""
    spec: Dict[str, Any] = {
        "replicas": draw(st.integers(min_value=REPLICA_MIN, max_value=REPLICA_MAX)),
        "image": draw(st.text(min_size=1, max_size=255)),
    }
    if draw(st.booleans()):
        spec["ports"] = draw(st.lists(st.integers(min_value=PORT_MIN, max_value=PORT_MAX), max_size=10))
    if draw(st.booleans()):
        spec["env"] = draw(st.dictionaries(st.text(min_size=1), st.text(min_size=1), max_size=20))
    if draw(st.booleans()):
        spec["resources"] = draw(st.dictionaries(st.text(min_size=1), st.text(min_size=1), max_size=10))
    return spec


@st.composite
def service_spec_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate valid Service specs."""
    spec: Dict[str, Any] = {
        "serviceType": draw(st.sampled_from(sorted(SERVICE_TYPES))),
        "targetPort": draw(st.integers(min_value=PORT_MIN, max_value=PORT_MAX)),
        "port": draw(st.integers(min_value=PORT_MIN, max_value=PORT_MAX)),
    }
    if draw(st.booleans()):
        spec["ports"] = draw(st.lists(st.integers(min_value=PORT_MIN, max_value=PORT_MAX), max_size=10))
    return spec


@st.composite
def ingress_spec_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate valid Ingress specs."""
    spec: Dict[str, Any] = {
        "host": draw(st.text(min_size=1, max_size=255)),
        "paths": draw(st.lists(st.text(min_size=1, max_size=255), min_size=1, max_size=20)),
    }
    return spec


@st.composite
def configmap_secret_spec_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate valid ConfigMap/Secret specs."""
    spec: Dict[str, Any] = {
        "data": draw(st.dictionaries(st.text(min_size=1), st.text(min_size=1), max_size=50)),
    }
    if draw(st.booleans()):
        spec["env"] = draw(st.dictionaries(st.text(min_size=1), st.text(min_size=1), max_size=20))
    return spec


@st.composite
def resource_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate a valid resource object."""
    rtype = draw(st.sampled_from(sorted(RESOURCE_TYPES)))
    name = draw(st.text(min_size=1, max_size=63, alphabet=st.characters(whitelist_categories=("Ll", "Lu", "Nd", "-"))))

    if rtype == "Deployment":
        spec = draw(deployment_spec_strategy())
    elif rtype == "Service":
        spec = draw(service_spec_strategy())
    elif rtype == "Ingress":
        spec = draw(ingress_spec_strategy())
    else:
        spec = draw(configmap_secret_spec_strategy())

    return {"type": rtype, "name": name, "spec": spec}


@st.composite
def valid_infra_spec_strategy(draw: st.DrawFn) -> Dict[str, Any]:
    """Generate a fully valid InfraSpec payload."""
    return {
        "version": draw(st.text(min_size=1, max_size=20)),
        "metadata": draw(valid_metadata_strategy()),
        "resources": draw(st.lists(resource_strategy(), min_size=1, max_size=20)),
    }


