class TestValidPayloads:
    """Tests that valid payloads pass validation."""

    def test_minimal_valid_payload(self, valid_payload):
        assert validate_infra_spec(valid_payload) == []

    def test_all_resource_types_valid(self):
        """Each resource type alone should validate."""
        for rtype in RESOURCE_TYPES:
            payload = {
                "version": "v1",
                "metadata": {"name": "x", "namespace": "default"},
                "resources": [{"type": rtype, "name": "r1", "spec": {}}],
            }
            errors = validate_infra_spec(payload)
            # Empty specs may produce type-specific errors, but no structural errors
            assert not any("required" in e or "unknown" in e for e in errors)

    def test_full_featured_payload(self):
        """Payload with all optional fields."""
        payload = {
            "version": "v2",
            "metadata": {"name": "full", "namespace": "prod"},
            "resources": [
                {
                    "type": "Deployment",
                    "name": "api",
                    "spec": {
                        "replicas": 5,
                        "image": "myapp:latest",
                        "ports": [8080, 9090],
                        "env": {"DEBUG": "true"},
                        "resources": {"cpu": "500m", "memory": "256Mi"},
                    },
                },
                {
                    "type": "Service",
                    "name": "api-svc",
                    "spec": {
                        "serviceType": "LoadBalancer",
                        "targetPort": 8080,
                        "port": 80,
                        "ports": [8080, 9090],
                    },
                },
                {
                    "type": "Ingress",
                    "name": "api-ing",
                    "spec": {"host": "api.example.com", "paths": ["/api", "/health"]},
                },
                {
                    "type": "ConfigMap",
                    "name": "api-cfg",
                    "spec": {"data": {"key": "value"}, "env": {"FOO": "bar"}},
                },
                {
                    "type": "Secret",
                    "name": "api-sec",
                    "spec": {"data": {"password": "base64=="}},
                },
            ],
        }
        assert validate_infra_spec(payload) == []

    def test_empty_resources_rejected(self):
        """Empty resources array should fail."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [],
        }
        errors = validate_infra_spec(payload)
        assert any("must not be empty" in e for e in errors)


