class TestInvalidPayloads:
    """Tests that invalid payloads are rejected with precise errors."""

    def test_missing_top_level_keys(self):
        payload = {"metadata": {"name": "x", "namespace": "default"}, "resources": []}
        errors = validate_infra_spec(payload)
        assert "version" in str(errors)

    def test_missing_metadata_keys(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {}}],
        }
        errors = validate_infra_spec(payload)
        assert any("namespace" in e for e in errors)

    def test_missing_resource_keys(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d"}],  # missing spec
        }
        errors = validate_infra_spec(payload)
        assert any("spec" in e and "required" in e for e in errors)

    def test_invalid_resource_type(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "DaemonSet", "name": "d", "spec": {}}],
        }
        errors = validate_infra_spec(payload)
        assert any("type" in e and "one of" in e for e in errors)

    def test_invalid_service_type(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Service", "name": "s", "spec": {"serviceType": "External"}}],
        }
        errors = validate_infra_spec(payload)
        assert any("serviceType" in e for e in errors)

    def test_port_out_of_range(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Service", "name": "s", "spec": {"port": 70000}}],
        }
        errors = validate_infra_spec(payload)
        assert any("port" in e and "range" in e for e in errors)

    def test_replicas_negative(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"replicas": -1}}],
        }
        errors = validate_infra_spec(payload)
        assert any("replicas" in e and "range" in e for e in errors)

    def test_unknown_spec_key(self):
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"replicas": 1, "unknownKey": "x"}}],
        }
        errors = validate_infra_spec(payload)
        assert any("unknown" in e for e in errors)

    def test_wrong_types(self):
        """Type mismatches should be caught."""
        payload = {
            "version": 123,  # should be string
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"replicas": "three"}}],
        }
        errors = validate_infra_spec(payload)
        assert any("version" in e for e in errors)
        assert any("replicas" in e and "integer" in e for e in errors)

    def test_non_object_payload(self):
        with pytest.raises(AttributeError):
            validate_infra_spec("not a dict")  # type: ignore


