class TestPropertyBased:
    """Hypothesis-driven property tests for robustness."""

    @settings(max_examples=200, suppress_health_check=[HealthCheck.too_slow])
    @given(valid_infra_spec_strategy())
    def test_valid_payloads_always_pass(self, payload):
        """Any payload generated by the valid strategy must validate."""
        assert validate_infra_spec(payload) == []

    @settings(max_examples=100)
    @given(st.dictionaries(st.text(), st.anything()))
    def test_arbitrary_dicts_never_crash(self, payload):
        """Arbitrary dicts should not raise unexpected exceptions."""
        try:
            errors = validate_infra_spec(payload)
            assert isinstance(errors, list)
        except (AttributeError, TypeError):
            pass  # acceptable for malformed inputs

    @settings(max_examples=100)
    @given(st.lists(st.text(), min_size=1, max_size=10))
    def test_resource_names_are_strings(self, names):
        """Resource names must be strings."""
        for name in names:
            payload = {
                "version": "v1",
                "metadata": {"name": "x", "namespace": "default"},
                "resources": [{"type": "Deployment", "name": name, "spec": {"replicas": 1}}],
            }
            errors = validate_infra_spec(payload)
            if not isinstance(name, str):
                assert any("name" in e and "string" in e for e in errors)

    @settings(max_examples=100)
    @given(st.integers(min_value=PORT_MIN, max_value=PORT_MAX))
    def test_valid_ports_accepted(self, port):
        """Valid ports should not produce port errors."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Service", "name": "s", "spec": {"port": port, "targetPort": port}}],
        }
        errors = validate_infra_spec(payload)
        assert not any("port" in e and "range" in e for e in errors)


