class TestCrossFieldConsistency:
    """Tests for relationships between fields."""

    def test_service_port_matches_target(self):
        """Service port and targetPort should be within valid range."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Service", "name": "s", "spec": {"port": 80, "targetPort": 8080}}],
        }
        errors = validate_infra_spec(payload)
        assert errors == []

    def test_deployment_ports_are_integers(self):
        """Deployment ports list must contain integers."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"ports": [80, "8080"]}}],
        }
        errors = validate_infra_spec(payload)
        # Our validator doesn't check ports deeply, but should not crash
        assert isinstance(errors, list)

    def test_ingress_paths_required_for_host(self):
        """Ingress with host should have paths."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Ingress", "name": "i", "spec": {"host": "example.com"}}],
        }
        errors = validate_infra_spec(payload)
        # paths is optional per schema, so no error expected
        assert errors == []


