class TestEdgeCases:
    """Boundary and unusual inputs."""

    def test_zero_replicas_valid(self):
        """Zero replicas is valid (scale-to-zero)."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"replicas": 0}}],
        }
        assert validate_infra_spec(payload) == []

    def test_max_replicas_valid(self):
        """Max replicas boundary."""
        payload = {
            "version": "v1",
            "metadata": {"name": "x", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "d", "spec": {"replicas": REPLICA_MAX}}],
        }
        assert validate_infra_spec(payload) == []

    def test_port_boundaries(self):
        """Port min and max boundaries."""
        for port in (PORT_MIN, PORT_MAX):
            payload = {
                "version": "v1",
                "metadata": {"name": "x", "namespace": "default"},
                "resources": [{"type": "Service", "name": "s", "spec": {"port": port, "targetPort": port}}],
            }
            assert validate_infra_spec(payload) == []

    def test_unicode_names(self):
        """Unicode names should be accepted (K8s allows some)."""
        payload = {
            "version": "v1",
            "metadata": {"name": "app-ünïcode", "namespace": "default"},
            "resources": [{"type": "Deployment", "name": "déplöy", "spec": {"replicas": 1}}],
        }
        errors = validate_infra_spec(payload)
        # Our validator doesn't enforce K8s naming rules strictly
        assert isinstance(errors, list)

    def test_empty_strings(self):
        """Empty strings for required fields."""
        payload = {
            "version": "",
            "metadata": {"name": "", "namespace": ""},
            "resources": [{"type": "Deployment", "name": "", "spec": {}}],
        }
        errors = validate_infra_spec(payload)
        # Empty strings are technically strings, so they pass type checks
        assert errors == []


