class TestPerformance:
    """Basic performance sanity checks."""

    def test_large_payload_validates_quickly(self):
        """100 resources should validate in reasonable time."""
        import time

        resources = [
            {
                "type": "Deployment",
                "name": f"app-{i}",
                "spec": {"replicas": i % 10, "image": f"img:{i}"},
            }
            for i in range(100)
        ]
        payload = {
            "version": "v1",
            "metadata": {"name": "large", "namespace": "default"},
            "resources": resources,
        }

        start = time.perf_counter()
        errors = validate_infra_spec(payload)
        elapsed = time.perf_counter() - start

        assert errors == []
        assert elapsed < 1.0, f"Validation took {elapsed:.3f}s, expected < 1s"


